  "alternatives": [
    "$\\frac{9}{16}$",
    "$\\frac{1}{2}$",
    "$\\frac{3}{4}$",
    "$\\frac{5}{8}$",
    "$\\frac{11}{32}$"
  ],
  "answer": "A",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Escolhe-se a dupla que terá a mesma cor de $\\binom32=3$ maneiras. Há 4 opções para a cor repetida e 3 para a cor diferente, totalizando $3\\cdot4\\cdot3=36$ casos favoráveis entre $4^3=64$ possíveis. Logo, $P=\\frac{36}{64}=\\frac{9}{16}$."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
  "sourceSha256": "0cf763533c927358f73db2e86320b655d00826acfd8592b5dfcd4bd74408b4dd",
